// Generates packages/ui/src/tokens.ts from design/design-system/tokens.json.
// tokens.json is the source of truth; never edit the generated file by hand.
// Run: npm run tokens
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const source = JSON.parse(readFileSync(`${root}design/design-system/tokens.json`, 'utf8'));
const THEME = 'paper';

const px = (value) => {
  const n = Number(String(value).replace(/px$/, ''));
  if (Number.isNaN(n)) throw new Error(`Not a px value: ${value}`);
  return n;
};
const camel = (name) => name.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const byName = (tokens, read) => Object.fromEntries(tokens.map((t) => [camel(t.name), read(t)]));

const color = byName(source.color.tokens, (t) => t.value[THEME]);
const space = byName(source.spacing.tokens, (t) => px(t.value));
const radius = byName(source.radius.tokens, (t) => px(t.value));
const border = byName(source.border.tokens, (t) => px(t.value));
const size = byName(source.size.tokens, (t) => px(t.value));
// React Native (new architecture) takes the CSS shadow string as `boxShadow`.
const shadow = byName(source.shadow.tokens, (t) => t.value[THEME]);
const duration = byName(source.duration.tokens, (t) => Math.round(parseFloat(t.value) * 1000));

const type = {};
for (const group of source.type.groups) {
  for (const style of group.styles) {
    const fontSize = px(style.fontSize);
    const entry = {
      family: group.family,
      fontSize,
      lineHeight: px(style.lineHeight),
      fontWeight: style.fontWeight,
    };
    if (style.letterSpacing) entry.letterSpacing = +(parseFloat(style.letterSpacing) * fontSize).toFixed(2);
    type[camel(style.name)] = entry;
  }
}

const out = `// Generated by scripts/build-tokens.mjs from design/design-system/tokens.json. Do not edit.
export const color = ${JSON.stringify(color, null, 2)} as const;

export const space = ${JSON.stringify(space, null, 2)} as const;

export const radius = ${JSON.stringify(radius, null, 2)} as const;

export const border = ${JSON.stringify(border, null, 2)} as const;

export const size = ${JSON.stringify(size, null, 2)} as const;

export const shadow = ${JSON.stringify(shadow, null, 2)} as const;

/** Milliseconds. */
export const duration = ${JSON.stringify(duration, null, 2)} as const;

/** fontSize, lineHeight and letterSpacing in px; family is a key of the font families. */
export const type = ${JSON.stringify(type, null, 2)} as const;
`;

writeFileSync(`${root}packages/ui/src/tokens.ts`, out);
console.log('Wrote packages/ui/src/tokens.ts');
